namespace sv_2a6c1b8a052048b792036dcecf27025f.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings
@using sv_2a6c1b8a052048b792036dcecf27025f.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (Profile is null)
    {
        <p>Loading...</p>
        return;
    }

    <div class="avatar-preview">
        <div class="avatar-image">
            @if (!string.IsNullOrEmpty(_displayAvatarUrl))
            {
                <img src="@_displayAvatarUrl" alt="Avatar" />
            }
            else
            {
                <div class="avatar-placeholder">👤</div>
            }
        </div>
        <span class="avatar-url-label">@_displayAvatarUrl</span>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="_email" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" rows="4" @bind="_bio" @bind:event="oninput"></textarea>
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="url" @bind="_displayAvatarUrl" @bind:event="oninput" />
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>

    @if (_showSuccess)
    {
        <div class="toast toast-success">Profile saved successfully!</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _displayAvatarUrl = "";
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_hasInitialized)
        {
            LoadFromProfile(Profile);
            _hasInitialized = true;
        }
    }

    private bool _hasInitialized;

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _displayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        var updated = new UserProfile(_displayName, _email, _displayAvatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        StateHasChanged();
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
            _hasInitialized = true;
        }
    }
}

@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings
@using sv_2a6c1b8a052048b792036dcecf27025f.Services

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (Prefs is null)
    {
        <p>Loading...</p>
        return;
    }

    <div class="toggle-group">
        <div class="toggle-item">
            <label class="toggle-switch">
                <input type="checkbox" @bind="_emailNotifications" />
                <span class="toggle-slider"></span>
            </label>
            <span class="toggle-label">Email Notifications</span>
        </div>

        <div class="toggle-item">
            <label class="toggle-switch">
                <input type="checkbox" @bind="_pushNotifications" />
                <span class="toggle-slider"></span>
            </label>
            <span class="toggle-label">Push Notifications</span>
        </div>

        <div class="toggle-item">
            <label class="toggle-switch">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span class="toggle-slider"></span>
            </label>
            <span class="toggle-label">Weekly Digest</span>
        </div>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in _allChannels)
        {
            <div class="channel-item">
                <label>
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    @channel
                </label>
            </div>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>
    </div>

    @if (_showSuccess)
    {
        <div class="toast toast-success">Preferences saved successfully!</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AllChannels { get; set; } = new() { "General", "Updates", "Marketing", "Engineering", "Support" };

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new();
    private bool _saving;
    private bool _showSuccess;
    private bool _hasInitialized;

    protected override void OnParametersSet()
    {
        _allChannels = AllChannels;
        if (Prefs is not null && !_hasInitialized)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            _hasInitialized = true;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _saving = true;
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        StateHasChanged();
    }
}

@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings
@using sv_2a6c1b8a052048b792036dcecf27025f.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (Settings is null)
    {
        <p>Loading...</p>
        return;
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>🔑 Change Password</span>
            <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
        </button>
        @if (_passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="error-message">@_passwordError</div>
                }
                @if (_passwordSuccess)
                {
                    <div class="toast toast-success">Password updated successfully!</div>
                }
                <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-item">
        <div class="toggle-item">
            <label class="toggle-switch">
                <input type="checkbox" checked="@Settings.TwoFactorEnabled" disabled />
                <span class="toggle-slider"></span>
            </label>
            <span class="toggle-label">Two-Factor Authentication</span>
            <span class="status-indicator @(Settings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    <div class="sessions-table-container">
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session != Settings.Sessions.First())
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-session-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
