        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>🔑 Change Password</span>
            <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
        </button>
        @if (_passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="error-message">@_passwordError</div>
                }
                @if (_passwordSuccess)
                {
                    <div class="toast toast-success">Password updated successfully!</div>
                }
                <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-item">
        <div class="toggle-item">
            <label class="toggle-switch">
                <input type="checkbox" checked="@Settings.TwoFactorEnabled" disabled />
                <span class="toggle-slider"></span>
            </label>
            <span class="toggle-label">Two-Factor Authentication</span>
            <span class="status-indicator @(Settings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

