@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings
@using sv_2a6c1b8a052048b792036dcecf27025f.Services

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (Profile is null)
    {
        <p>Loading...</p>
        return;
    }

    <div class="avatar-preview">
        <div class="avatar-image">
            @if (!string.IsNullOrEmpty(_displayAvatarUrl))
            {
                <img src="@_displayAvatarUrl" alt="Avatar" />
            }
            else
            {
                <div class="avatar-placeholder">👤</div>
            }
        </div>
        <span class="avatar-url-label">@_displayAvatarUrl</span>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="_email" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" rows="4" @bind="_bio" @bind:event="oninput"></textarea>
    </div>

    <div class="form-group">
        <label for="avatarUrl">Avatar URL</label>
        <input id="avatarUrl" type="url" @bind="_displayAvatarUrl" @bind:event="oninput" />
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>

    @if (_showSuccess)
    {
        <div class="toast toast-success">Profile saved successfully!</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _displayAvatarUrl = "";
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_hasInitialized)
        {
            LoadFromProfile(Profile);
            _hasInitialized = true;
        }
    }

    private bool _hasInitialized;

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _displayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        var updated = new UserProfile(_displayName, _email, _displayAvatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        StateHasChanged();
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
            _hasInitialized = true;
        }
    }
}

