@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings
@using sv_2a6c1b8a052048b792036dcecf27025f.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (Settings is null)
    {
        <p>Loading...</p>
        return;
    }

    <!-- Theme Selector -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            <label class="radio-item">
                <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange='() => _theme = "Light"' />
                <span>☀️ Light</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange='() => _theme = "Dark"' />
                <span>🌙 Dark</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange='() => _theme = "System"' />
                <span>💻 System</span>
            </label>
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            <label class="radio-item">
                <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange='() => _fontSize = "Small"' />
                <span>Small</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange='() => _fontSize = "Medium"' />
                <span>Medium</span>
            </label>
            <label class="radio-item">
                <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange='() => _fontSize = "Large"' />
                <span>Large</span>
            </label>
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="_language">
            <option value="en">English</option>
            <option value="es">Spanish</option>
            <option value="fr">French</option>
            <option value="de">German</option>
            <option value="ja">Japanese</option>
            <option value="zh">Chinese</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="toggle-item">
        <label class="toggle-switch">
            <input type="checkbox" @bind="_compactMode" />
            <span class="toggle-slider"></span>
        </label>
        <span class="toggle-label">Compact Mode</span>
    </div>

    <!-- Live Preview -->
    <div class="appearance-preview @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            <button class="btn btn-primary">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
            @(_saving ? "Saving..." : "Save")
        </button>
    </div>

    @if (_showSuccess)
    {
        <div class="toast toast-success">Appearance settings saved!</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private bool _showSuccess;
    private bool _hasInitialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_hasInitialized)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
            _hasInitialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLower()} preview-font-{_fontSize.ToLower()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        StateHasChanged();
    }
}

arguments.file_text:
namespace sv_2a6c1b8a052048b792036dcecf27025f.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@namespace sv_2a6c1b8a052048b792036dcecf27025f.Components.Pages.Settings
@using sv_2a6c1b8a052048b792036dcecf27025f.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@_profile" OnSave="SaveProfile" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotifications" />
                break;
            case "Security":
                <SecuritySection Settings="@_securitySettings"
                                 OnChangePassword="ChangePassword"
                                 OnRevokeSession="RevokeSession" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@_appearanceSettings" OnSave="SaveAppearance" />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData(_activeSection);
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        await LoadSectionData(section);
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "Profile":
                _profile ??= await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                _notificationPrefs ??= await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                _securitySettings ??= await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                _appearanceSettings ??= await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePassword((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
    }
}

/* Settings Layout */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--bs-gray-100, #f8f9fa);
    border-right: 1px solid var(--bs-gray-300, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
