toolArgs.file_text:
/* Settings Layout */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--bs-gray-100, #f8f9fa);
    border-right: 1px solid var(--bs-gray-300, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left-color 0.2s;
    border-left: 3px solid transparent;
    color: var(--bs-gray-700, #495057);
}

.settings-nav-item:hover {
    background: var(--bs-gray-200, #e9ecef);
}

.settings-nav-item.active {
    background: var(--bs-white, #fff);
    border-left-color: var(--bs-primary, #0d6efd);
    color: var(--bs-primary, #0d6efd);
    font-weight: 600;
}

.nav-icon {
    font-size: 1.2rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--bs-gray-800, #343a40);
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.15rem;
    font-weight: 600;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: var(--bs-gray-700, #495057);
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--bs-gray-300, #dee2e6);
    border-radius: 0.375rem;
    font-size: 0.95rem;
    transition: border-color 0.2s, box-shadow 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: var(--bs-primary, #0d6efd);
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: var(--bs-primary, #0d6efd);
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-secondary {
    background: var(--bs-gray-200, #e9ecef);
    color: var(--bs-gray-700, #495057);
}

.btn-secondary:hover:not(:disabled) {
    background: var(--bs-gray-300, #dee2e6);
}

.btn-danger {
    background: var(--bs-danger, #dc3545);
    color: #fff;
}

.btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid var(--bs-gray-200, #e9ecef);
    border-radius: 0.5rem;
    background: var(--bs-gray-50, #f8f9fa);
}

.avatar-image img {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
}

.avatar-placeholder {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: var(--bs-gray-300, #dee2e6);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
}

.avatar-url-label {
    font-size: 0.85rem;
    color: var(--bs-gray-500, #adb5bd);
    word-break: break-all;
}

/* Toggle Switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    cursor: pointer;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    inset: 0;
    background: var(--bs-gray-300, #dee2e6);
    border-radius: 24px;
    transition: background-color 0.3s;
}

.toggle-slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.3s;
}

.toggle-switch input:checked + .toggle-slider {
    background: var(--bs-primary, #0d6efd);
}

.toggle-switch input:checked + .toggle-slider::before {
    transform: translateX(20px);
}

.toggle-label {
    font-weight: 500;
}

/* Channel List */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    border: 1px solid var(--bs-gray-200, #e9ecef);
    border-radius: 0.375rem;
}

.channel-item label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid var(--bs-gray-200, #e9ecef);
    border-radius: 0.5rem;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: var(--bs-gray-50, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background: var(--bs-gray-100, #f8f9fa);
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid var(--bs-gray-200, #e9ecef);
}

/* Security */
.security-item {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid var(--bs-gray-200, #e9ecef);
    border-radius: 0.5rem;
}

.status-indicator {
    margin-left: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 1rem;
    font-size: 0.75rem;
    font-weight: 600;
}

.status-enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-disabled {
    background: #f8d7da;
    color: #842029;
}

.info-text {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: var(--bs-gray-500, #adb5bd);
}

.current-session-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    background: #cfe2ff;
    color: #084298;
    border-radius: 0.25rem;
    font-weight: 500;
}

/* Sessions Table */
.sessions-table-container {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--bs-gray-200, #e9ecef);
}

.sessions-table th {
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    color: var(--bs-gray-500, #adb5bd);
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Appearance Preview */
.appearance-preview {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid var(--bs-gray-300, #dee2e6);
    border-radius: 0.5rem;
    transition: all 0.3s ease;
}

.appearance-preview h4 {
    margin-bottom: 0.5rem;
}

.preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid var(--bs-gray-200, #e9ecef);
    border-radius: 0.375rem;
    background: #fff;
}

/* Preview theme variants */
.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-theme-dark .preview-card {
    background: #313244;
    border-color: #45475a;
    color: #cdd6f4;
}

.preview-theme-light {
    background: #ffffff;
    color: #1e1e2e;
}

.preview-theme-system {
    background: #f8f9fa;
    color: #343a40;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact mode */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

/* Error */
.error-message {
    color: var(--bs-danger, #dc3545);
    font-size: 0.875rem;
    margin-bottom: 0.75rem;
}

/* Dialog Overlay */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: #fff;
    border-radius: 0.5rem;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
}

.dialog h4 {
    margin-bottom: 0.75rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

